package com.snoworca.naruserve.proxy;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import com.snoworca.naruserve.RestApp;
import com.snoworca.naruserve.proxy.ProxyTlsTest.TlsBackend;
import com.snoworca.naruserve.testing.InMemoryHttpAdapter;
import com.snoworca.naruserve.testing.InMemoryHttpAdapter.ClientRequest;
import com.snoworca.naruserve.testing.InMemoryHttpAdapter.ClientResponse;
import com.snoworca.naruserve.testing.TestApp;
import java.io.File;
import java.security.Key;
import java.security.KeyStore;
import java.security.cert.Certificate;
import java.security.cert.CertificateExpiredException;
import java.security.cert.X509Certificate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.TimeUnit;
import javax.net.ssl.KeyManagerFactory;
import javax.net.ssl.SSLContext;
import org.junit.Test;

public class ReviewProbeExpiredPresentedCopyTest {
    @Test(timeout = 60000)
    public void anExpiredPresentedSelfSignedCopyOfAValidGivenCertificateIsConnectFailed() throws Exception {
        File dir = java.nio.file.Files.createTempDirectory("review-probe").toFile();
        InMemoryHttpAdapter adapter = new InMemoryHttpAdapter();
        TestApp t = TestApp.create(adapter);
        RestApp app = t.app();
        List<Throwable> errors = Collections.synchronizedList(new ArrayList<Throwable>());
        TlsBackend backend = null;
        try {
            TestCertificates.keytool(dir, "-genkeypair", "-alias", "dup", "-keyalg", "RSA", "-keysize", "2048",
                    "-dname", "CN=localhost", "-ext", "SAN=dns:localhost,ip:127.0.0.1", "-validity", "3",
                    "-keystore", "dup.p12");
            TestCertificates.keytool(dir, "-exportcert", "-rfc", "-alias", "dup", "-keystore", "dup.p12", "-file",
                    "dup.pem");
            TestCertificates.keytool(dir, "-certreq", "-alias", "dup", "-keystore", "dup.p12", "-file", "dup.csr");
            TestCertificates.keytool(dir, "-gencert", "-rfc", "-alias", "dup", "-keystore", "dup.p12", "-infile",
                    "dup.csr", "-outfile", "dupold.pem", "-ext", "SAN=dns:localhost,ip:127.0.0.1", "-startdate",
                    "2000/01/01", "-validity", "2");
            String validPem = TestCertificates.read(new File(dir, "dup.pem"));
            X509Certificate valid = TestCertificates.parse(validPem);
            X509Certificate expired = TestCertificates.parse(TestCertificates.read(new File(dir, "dupold.pem")));
            assertEquals(valid.getSubjectX500Principal(), expired.getSubjectX500Principal());
            assertEquals(valid.getPublicKey(), expired.getPublicKey());
            expired.verify(expired.getPublicKey());
            valid.checkValidity();
            try { expired.checkValidity(); fail("fixture: must be expired"); } catch (CertificateExpiredException ok) { }
            KeyStore source = TestCertificates.load(new File(dir, "dup.p12"));
            char[] password = TestCertificates.PASSWORD.toCharArray();
            Key key = source.getKey("dup", password);
            KeyStore presenting = KeyStore.getInstance("PKCS12");
            presenting.load(null, null);
            presenting.setKeyEntry("server", key, password, new Certificate[] {expired});
            KeyManagerFactory kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
            kmf.init(presenting, password);
            SSLContext server = SSLContext.getInstance("TLS");
            server.init(kmf.getKeyManagers(), null, null);
            backend = new TlsBackend(server);
            app.use("/api", Proxy.to("https://localhost:" + backend.port()).trustCertificates(validPem));
            app.onError((error, req, res) -> errors.add(error));
            t.start();
            ClientResponse r = adapter.send(ClientRequest.of("GET", "/api/x"));
            System.out.println("CAUSE " + (errors.isEmpty() ? null : errors.get(0).getCause()));
            assertEquals(502, r.status());
            assertTrue(errors.get(0) instanceof ProxyException);
            assertEquals(ProxyException.Kind.CONNECT_FAILED, ((ProxyException) errors.get(0)).kind());
            assertEquals(0, backend.requestBytes());
        } finally {
            app.shutdown(2, TimeUnit.SECONDS);
            if (backend != null) { backend.close(); }
            TestCertificates.delete(dir);
        }
    }
}

package com.snoworca.naruserve.proxy;

import static org.junit.Assert.assertEquals;

import com.snoworca.naruserve.proxy.ProxyTlsTest.TlsBackend;
import java.io.IOException;
import java.io.InputStream;
import java.security.KeyStore;
import java.util.Arrays;
import javax.net.ssl.SSLContext;
import javax.net.ssl.SSLSession;
import javax.net.ssl.SSLSocket;
import javax.net.ssl.SSLSocketFactory;
import javax.net.ssl.TrustManagerFactory;
import org.junit.Test;

/** Does the creation-time oracle of fr_PROXY_022_AC3_eachConnectionThroughTrustCertificatesRunsAFullHandshake detect resumption? */
public class ReviewProbeResumptionOracleTest {
    @Test(timeout = 30000)
    public void aSingleContextFactoryResumesAndKeepsTheCreationTime() throws Exception {
        KeyStore trust = KeyStore.getInstance(KeyStore.getDefaultType());
        trust.load(null, null);
        trust.setCertificateEntry("self", TestCertificates.selfSigned());
        TrustManagerFactory tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
        tmf.init(trust);
        SSLContext client = SSLContext.getInstance("TLS");
        client.init(null, tmf.getTrustManagers(), null);
        SSLSocketFactory f = client.getSocketFactory();
        try (TlsBackend backend = new TlsBackend(TestCertificates.selfSignedServer())) {
            SSLSession first = handshakeAndReadResponse(f, backend.port());
            Thread.sleep(50);
            SSLSession second = handshakeAndReadResponse(f, backend.port());
            System.out.println("PROTO " + first.getProtocol() + " first=" + first.getCreationTime() + " id="
                    + Arrays.toString(first.getId()) + " second=" + second.getCreationTime() + " id="
                    + Arrays.toString(second.getId()) + " sameObject=" + (first == second));
            assertEquals(first.getCreationTime(), second.getCreationTime());
        }
    }

    private static SSLSession handshakeAndReadResponse(SSLSocketFactory f, int port) throws IOException {
        try (SSLSocket s = (SSLSocket) f.createSocket("localhost", port)) {
            s.startHandshake();
            SSLSession session = s.getSession();
            s.getOutputStream().write("GET /api/x HTTP/1.1\r\nHost: localhost\r\n\r\n"
                    .getBytes(java.nio.charset.StandardCharsets.ISO_8859_1));
            s.getOutputStream().flush();
            InputStream in = s.getInputStream();
            while (in.read() != -1) { }
            return session;
        }
    }
}
